-- Queries for the users table. Generated into storage/generated by sqlc.
-- See sqlc.yaml at the project root for configuration.

-- name: GetUserByID :one
SELECT id, email, username, name, role, is_external, created_at, last_login_at, metadata
FROM users
WHERE id = $1;

-- name: GetUserByEmail :one
-- Public lookup by email — does NOT include password_hash so the hash cannot
-- accidentally leak through a non-auth code path. The auth flow uses
-- GetUserCredentialsByEmail instead.
SELECT id, email, username, name, role, created_at, last_login_at, metadata
FROM users
WHERE lower(email) = lower($1);

-- name: GetUserCredentialsByEmail :one
-- Auth-only: returns the bcrypt hash alongside the user row for password
-- verification. Caller must never echo password_hash back over the wire —
-- handlers convert to a hash-free response struct before responding.
--
-- deactivated_at is included so the login flow can fail closed in a
-- single round-trip (R3.1 C1) — a separate SELECT for the deactivation
-- check would silently fall through on transient DB errors and let a
-- deactivated user authenticate with valid credentials.
SELECT id, email, username, name, role, password_hash, is_external, last_login_at, created_at, deactivated_at
FROM users
WHERE lower(email) = lower($1);

-- name: UpdateLastLogin :exec
UPDATE users
SET last_login_at = now()
WHERE id = $1;

-- name: CreateUser :one
-- Insert path used by the bootstrap admin flow (and later by registration in
-- R5.x). password_hash is required by the users_auth_method CHECK whenever
-- keycloak_sub is NULL — bootstrap always provides one.
INSERT INTO users (id, email, username, name, role, password_hash, created_at, metadata)
VALUES ($1, $2, $3, $4, $5, $6, now(), '{}'::jsonb)
RETURNING id, email, username, name, role, created_at, metadata;

-- name: CountUsers :one
SELECT count(*) FROM users;
